function applyTranslations() {
    updateLangFlag();
    const lang = state.currentLang || 'hu';
    const dict = translations[lang] || translations.hu;
    
    document.querySelectorAll('[data-i18n], option[data-i18n]').forEach(el => {
        const key = el.getAttribute('data-i18n');
        if (dict[key]) {
            if (el.tagName === 'INPUT' && (el.type === 'button' || el.type === 'submit')) {
                el.value = dict[key];
            } else {
                el.textContent = dict[key];
            }
        }
    });
    
    document.querySelectorAll('[data-i18n-placeholder]').forEach(el => {
        const key = el.getAttribute('data-i18n-placeholder');
        if (dict[key]) {
            el.placeholder = dict[key];
        }
    });
}

window.toggleLanguage = function() {
    state.currentLang = state.currentLang === 'hu' ? 'en' : 'hu';
    saveStateToLocalStorage();
    applyTranslations();
    updateAppView();
    updateLangFlag();
    
    // Auto-refresh active modals with new language strings
    const flatModal = document.getElementById("flat-detail-modal");
    if (flatModal && flatModal.style.display === "flex" && state.currentFlatDetailNum) {
        openFlatDetailModal(state.currentFlatDetailNum);
    }
    
    const fsModal = document.getElementById("fullscreen-tx-modal");
    if (fsModal && fsModal.style.display === "flex") {
        openFullscreenTx(typeof fullscreenType !== 'undefined' ? fullscreenType : 'global');
    }
};

function updateLangFlag() {
    const flagImg = document.getElementById('lang-flag-img');
    if (flagImg) {
        const isHu = (state.currentLang === 'hu' || !state.currentLang);
        flagImg.src = isHu ? 'https://flagcdn.com/gb.svg' : 'https://flagcdn.com/hu.svg';
        flagImg.alt = isHu ? 'EN' : 'HU';
        flagImg.title = isHu ? 'Switch to English' : 'Váltás magyar nyelvre';
    }
}

