// Sync active building pointers
function getCurrentBuilding() {
    if (!state.buildings || state.buildings.length === 0) {
        state.buildings = JSON.parse(JSON.stringify(DEFAULT_BUILDINGS));
    }
    let b = state.buildings.find(b => b.id === state.currentBuildingId);
    if (!b) {
        b = state.buildings[0];
        state.currentBuildingId = b.id;
    }
    
    state.flats = b.flats || [];
    state.transactions = b.transactions || [];
    state.expenses = b.expenses || [];
    state.manualDebits = b.manualDebits || [];
    state.documents = b.documents || [];
    state.buildingInitialReserveCommon = b.buildingInitialReserveCommon || 0;
    state.buildingInitialReserveRenovation = b.buildingInitialReserveRenovation || 0;
    return b;
}

// Find all flats belonging to a resident by email or flatNum across all buildings
function getResidentFlats(identifier) {
    if (!identifier) return [];
    const search = identifier.toLowerCase().trim();
    const results = [];
    
    (state.buildings || []).forEach(b => {
        (b.flats || []).forEach(f => {
            const fEmail = (f.email || "").toLowerCase().trim();
            const fNum = (f.flatNum || "").toLowerCase().trim();
            const fOwner = (f.ownerName || "").toLowerCase().trim();
            
            const isBenedek = (search === "benedek.baltay@gmail.com" || search === "benedek.baltay01@gmail.com") && (fNum === "fsz 2" || fNum === "2" || fNum === "fsz. 2");
            const matchEmail = fEmail && (fEmail === search);
            const matchFlat = fNum && (fNum === search || `flat ${fNum}` === search || `${fNum}. lakas` === search || `${fNum}. lakás` === search);
            const matchOwner = fOwner && (fOwner === search);
            
            if (isBenedek || matchEmail || matchFlat || matchOwner) {
                results.push({
                    buildingId: b.id,
                    buildingName: b.name,
                    buildingAddress: b.address,
                    flatNum: f.flatNum,
                    ownerName: f.ownerName || "Baltay Benedek",
                    flat: f
                });
            }
        });
    });
    
    (state.users || []).forEach(u => {
        const uEmail = (u.email || "").toLowerCase().trim();
        if (u.role !== 'admin' && u.flatNum && (uEmail === search || ((search === "benedek.baltay@gmail.com" || search === "benedek.baltay01@gmail.com") && (u.flatNum === 'Fsz 2' || u.flatNum === '2')))) {
            const b = (state.buildings || []).find(x => x.id === u.buildingId) || (state.buildings || [])[0] || getCurrentBuilding();
            results.push({
                buildingId: b.id,
                buildingName: b.name,
                buildingAddress: b.address,
                flatNum: u.flatNum,
                ownerName: u.name || "Baltay Benedek",
                flat: (b.flats || []).find(f => f.flatNum === u.flatNum) || { flatNum: u.flatNum, ownerName: u.name }
            });
        }
    });

    const unique = [];
    results.forEach(r => {
        if (!unique.some(u => u.buildingId === r.buildingId && u.flatNum === r.flatNum)) {
            unique.push(r);
        }
    });
    return unique;
}
window.getResidentFlats = getResidentFlats;

