function processUploadedFiles(fileList, targetArray, renderCallback) {
    if (!fileList || fileList.length === 0) return;
    const promises = Array.from(fileList).map(file => {
        return new Promise(resolve => {
            const reader = new FileReader();
            let sizeStr = (file.size / 1024).toFixed(0) + " KB";
            if (file.size > 1024 * 1024) {
                sizeStr = (file.size / (1024 * 1024)).toFixed(1) + " MB";
            }
            reader.onload = function(e) {
                resolve({
                    id: "att-" + Date.now() + "-" + Math.floor(Math.random() * 10000),
                    fileName: file.name,
                    fileSize: sizeStr,
                    fileType: file.name.split('.').pop().toLowerCase(),
                    uploadDate: new Date().toISOString().split('T')[0],
                    fileData: e.target.result
                });
            };
            reader.onerror = () => resolve(null);
            reader.readAsDataURL(file);
        });
    });
    
    Promise.all(promises).then(results => {
        results.filter(Boolean).forEach(item => targetArray.push(item));
        if (typeof renderCallback === 'function') renderCallback();
    });
}

