window.findTxItem = function(txId) {
    if (!txId) return null;
    const curB = getCurrentBuilding();
    let found = (curB.transactions || []).find(t => t.id === txId) ||
                (curB.expenses || []).find(e => e.id === txId) ||
                (curB.manualDebits || []).find(d => d.id === txId);
    if (found) return found;
    
    found = (state.transactions || []).find(t => t.id === txId) ||
            (state.expenses || []).find(e => e.id === txId) ||
            (state.manualDebits || []).find(d => d.id === txId);
    if (found) return found;
    
    for (const b of (state.buildings || [])) {
        found = (b.transactions || []).find(t => t.id === txId) ||
                (b.expenses || []).find(e => e.id === txId) ||
                (b.manualDebits || []).find(d => d.id === txId);
        if (found) return found;
    }
    return null;
};

window.downloadTxAttachment = function(txId, attId) {
    const tx = window.findTxItem(txId);
    if (!tx) {
        alert("Tranzakció nem található.");
        return;
    }
    const atts = tx.attachments || (tx.attachment ? [tx.attachment] : []);
    const att = attId ? atts.find(a => a.id === attId) : atts[0];
    if (!att || !att.fileData) {
        alert("Dokumentum nem található vagy sérült.");
        return;
    }
    
    const link = document.createElement("a");
    link.href = att.fileData;
    link.download = att.fileName || "dokumentum.pdf";
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    if (typeof playNotificationSound === 'function') playNotificationSound('success');
};

window.downloadAttachmentDirect = function(attId) {
    const att = editFormExistingAttachments.find(a => a.id === attId) || editFormNewAttachments.find(a => a.id === attId);
    if (!att || !att.fileData) return;
    const link = document.createElement("a");
    link.href = att.fileData;
    link.download = att.fileName || "dokumentum.pdf";
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    if (typeof playNotificationSound === 'function') playNotificationSound('success');
};

function renderTxAttachmentsHtml(item) {
    if (!item) return '';
    const atts = item.attachments || (item.attachment ? [item.attachment] : []);
    if (!atts || atts.length === 0) return '';
    
    return `
        <div style="display:flex; flex-wrap:wrap; gap:5px; margin-top:4px;">
            ${atts.map(att => `
                <button type="button" class="tx-attachment-badge" onclick="event.stopPropagation(); window.downloadTxAttachment('${item.id}', '${att.id}')" title="Letöltés: ${att.fileName} (${att.fileSize || ''})">
                    <i data-lucide="paperclip" style="width:12px;height:12px;"></i>
                    <span style="max-width:160px; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;">${att.fileName}</span>
                </button>
            `).join('')}
        </div>
    `;
}

let _tenantCombinedData = [];

function renderCombinedTenantTable(flatNum) {
    const isEn = (state.currentLang === "en");

    const timelineKK = getFlatLedgerTimeline(flatNum, "Közös Költség");
    const timelineFA = getFlatLedgerTimeline(flatNum, "Felújítási Alap");

    _tenantCombinedData = [
        ...timelineKK.map(item => ({ ...item, accountKey: "KK" })),
        ...timelineFA.map(item => ({ ...item, accountKey: "FA" }))
    ];
    _tenantCombinedData.sort((a, b) => new Date(b.date) - new Date(a.date));

    // Clear the search input when re-rendering (e.g. on login)
    const searchInput = document.getElementById("tenant-tx-search");
    if (searchInput) searchInput.value = "";

    _renderTenantCombinedRows(_tenantCombinedData, true);
}

function _renderTenantCombinedRows(data, previewOnly) {
    const isEn = (state.currentLang === "en");
    const tbody = document.getElementById("tenant-tbody-combined");
    if (!tbody) return;
    tbody.innerHTML = "";

    const PREVIEW_COUNT = 5;
    const displayData = previewOnly ? data.slice(0, PREVIEW_COUNT) : data;

    // Show/hide "View all" row
    const showAllRow = document.getElementById("tenant-tx-show-all-row");
    const showAllLabel = document.getElementById("tenant-tx-show-all-label");
    if (showAllRow) {
        showAllRow.style.display = data.length > PREVIEW_COUNT ? "block" : "none";
    }
    if (showAllLabel) {
        const remaining = data.length;
        showAllLabel.textContent = isEn
            ? `View all ${remaining} transactions`
            : `Teljes lista megtekintése (${remaining} tétel)`;
    }

    if (displayData.length === 0) {
        tbody.innerHTML = `
            <tr>
                <td colspan="5" style="padding:0; border:none;">
                    <div style="display:flex; flex-direction:column; align-items:center; justify-content:center; padding:44px 20px; text-align:center; background:var(--bg-body); border-radius:var(--radius-md); margin:12px; border:1px dashed var(--border-color);">
                        <div style="width:52px; height:52px; border-radius:50%; background:var(--primary-light); color:var(--primary); display:flex; align-items:center; justify-content:center; margin-bottom:12px;">
                            <i data-lucide="search-x" style="width:24px; height:24px;"></i>
                        </div>
                        <h4 style="margin:0 0 6px 0; font-size:15px; font-weight:700; color:var(--text-main);">
                            ${isEn ? "No transactions found" : "Nem található tranzakció"}
                        </h4>
                        <p style="margin:0; font-size:13px; color:var(--text-muted); max-width:360px; line-height:1.4;">
                            ${isEn ? "No records match your search criteria. Try a different keyword or date." : "Nincs a keresési feltételnek megfelelő tétel. Próbáljon meg más dátumot, összeget vagy megjegyzést keresni."}
                        </p>
                    </div>
                </td>
            </tr>
        `;
        if (window.lucide) lucide.createIcons();
        return;
    }

    displayData.forEach(item => {
        const row = document.createElement("tr");
        const isDebit = item.type === "Debit";
        const isNegative = isDebit || item.amount < 0;
        const amountHtml = isNegative
            ? `<span class="text-danger" style="font-weight:600;">-${formatCurrency(Math.abs(item.amount))}</span>`
            : `<span class="text-success" style="font-weight:600;">+${formatCurrency(item.amount)}</span>`;
        const typeBadge = isDebit
            ? `<span class="status-badge status-expense"><i data-lucide="arrow-down" style="width:12px;height:12px;"></i> ${isEn ? "Fee" : "Előírás"}</span>`
            : `<span class="status-badge status-verified"><i data-lucide="arrow-up" style="width:12px;height:12px;"></i> ${isEn ? "Payment" : "Befizetés"}</span>`;
        const badgeColor = item.accountKey === "KK" ? "var(--primary)" : "var(--purple)";

        const attsHtml = renderTxAttachmentsHtml(item);
        row.innerHTML = `
            <td style="white-space:nowrap;">${item.date}</td>
            <td><span style="background:${badgeColor};color:white;padding:2px 6px;border-radius:4px;font-size:11px;font-weight:700;">${item.accountKey}</span></td>
            <td>${typeBadge}</td>
            <td style="text-align:right;">${amountHtml}</td>
            <td style="color:var(--text-muted);font-size:13px;">${item.comment || "–"}${attsHtml}</td>
        `;
        tbody.appendChild(row);
    });

    if (window.lucide) lucide.createIcons();
}

window.filterTenantCombinedTable = function(val) {
    const searchInput = document.getElementById("tenant-tx-search");
    const query = ((val !== undefined ? val : searchInput?.value) || "").toLowerCase().trim();
    const filtered = query ? _tenantCombinedData.filter(item => _tenantMatchesQuery(item, query)) : _tenantCombinedData;
    // When searching, show all matched records without 5-item cut-off; when empty, show preview of 5
    _renderTenantCombinedRows(filtered, !query);
};

function _tenantMatchesQuery(item, query) {
    return (
        (item.date && item.date.includes(query)) ||
        (item.comment && item.comment.toLowerCase().includes(query)) ||
        Math.abs(item.amount).toString().includes(query) ||
        (item.accountKey && item.accountKey.toLowerCase().includes(query)) ||
        (item.type === "Debit" && ("előírás".includes(query) || "fee".includes(query))) ||
        (item.type === "Credit" && ("befizetés".includes(query) || "payment".includes(query)))
    );
}

window.openTenantFullscreen = function() {
    const isEn = (state.currentLang === "en");
    const modal = document.getElementById("tenant-fullscreen-modal");
    if (!modal) return;

    // Clear search
    const searchEl = document.getElementById("tenant-fullscreen-search");
    if (searchEl) searchEl.value = "";
    const clearBtn = document.getElementById("tenant-fullscreen-search-clear");
    if (clearBtn) clearBtn.style.display = "none";

    _renderTenantFullscreenRows(_tenantCombinedData);
    modal.style.display = "flex";
    document.body.style.overflow = "hidden";
    if (window.lucide) lucide.createIcons();
};

window.closeTenantFullscreen = function() {
    const modal = document.getElementById("tenant-fullscreen-modal");
    if (modal) modal.style.display = "none";
    document.body.style.overflow = "";
};

window.filterTenantFullscreen = function(query) {
    query = (query || "").toLowerCase().trim();
    const clearBtn = document.getElementById("tenant-fullscreen-search-clear");
    if (clearBtn) clearBtn.style.display = query ? "flex" : "none";
    const filtered = query ? _tenantCombinedData.filter(item => _tenantMatchesQuery(item, query)) : _tenantCombinedData;
    _renderTenantFullscreenRows(filtered);
};

function _renderTenantFullscreenRows(data) {
    const isEn = (state.currentLang === "en");
    const tbody = document.getElementById("tenant-fullscreen-tbody");
    if (!tbody) return;
    tbody.innerHTML = "";

    if (data.length === 0) {
        tbody.innerHTML = `
            <tr>
                <td colspan="5" style="padding:0; border:none;">
                    <div style="display:flex; flex-direction:column; align-items:center; justify-content:center; padding:60px 24px; text-align:center; background:var(--bg-body); border-radius:var(--radius-md); margin:20px; border:1px dashed var(--border-color);">
                        <div style="width:60px; height:60px; border-radius:50%; background:var(--primary-light); color:var(--primary); display:flex; align-items:center; justify-content:center; margin-bottom:16px;">
                            <i data-lucide="search-x" style="width:28px; height:28px;"></i>
                        </div>
                        <h4 style="margin:0 0 8px 0; font-size:17px; font-weight:700; color:var(--text-main);">
                            ${isEn ? "No transactions found" : "Nem található tranzakció"}
                        </h4>
                        <p style="margin:0; font-size:13.5px; color:var(--text-muted); max-width:400px; line-height:1.5;">
                            ${isEn ? "No transactions matched your search criteria. Clear the search bar to see all items." : "Nincs a megadott keresésnek megfelelő tranzakció. Törölje a keresőmezőt a teljes lista megjelenítéséhez."}
                        </p>
                    </div>
                </td>
            </tr>
        `;
        if (window.lucide) lucide.createIcons();
        return;
    }

    data.forEach(item => {
        const row = document.createElement("tr");
        const isDebit = item.type === "Debit";
        const isNegative = isDebit || item.amount < 0;
        const amountHtml = isNegative
            ? `<span class="text-danger" style="font-weight:600;">-${formatCurrency(Math.abs(item.amount))}</span>`
            : `<span class="text-success" style="font-weight:600;">+${formatCurrency(item.amount)}</span>`;
        const typeBadge = isDebit
            ? `<span class="status-badge status-expense"><i data-lucide="arrow-down" style="width:12px;height:12px;"></i> ${isEn ? "Fee" : "Előírás"}</span>`
            : `<span class="status-badge status-verified"><i data-lucide="arrow-up" style="width:12px;height:12px;"></i> ${isEn ? "Payment" : "Befizetés"}</span>`;
        const badgeColor = item.accountKey === "KK" ? "var(--primary)" : "var(--purple)";

        const attsHtml = renderTxAttachmentsHtml(item);
        row.innerHTML = `
            <td style="white-space:nowrap;">${item.date}</td>
            <td><span style="background:${badgeColor};color:white;padding:2px 6px;border-radius:4px;font-size:11px;font-weight:700;">${item.accountKey}</span></td>
            <td>${typeBadge}</td>
            <td style="text-align:right;">${amountHtml}</td>
            <td style="color:var(--text-muted);font-size:13px;">${item.comment || "–"}${attsHtml}</td>
        `;
        tbody.appendChild(row);
    });

    if (window.lucide) lucide.createIcons();
}

function renderTimelineTable(tbodyId, flatNum, targetAccount) {
    const isEn = (state.currentLang === "en");
    const tbody = document.getElementById(tbodyId);
    if (!tbody) return;
    tbody.innerHTML = "";
    
    const timeline = getFlatLedgerTimeline(flatNum, targetAccount);
    
    if (timeline.length === 0) {
        tbody.innerHTML = `<tr><td colspan="5" style="text-align: center; color: var(--text-muted);">${isEn ? "No transactions found." : "Nem található tranzakció."}</td></tr>`;
        return;
    }
    
    timeline.forEach(item => {
        const row = document.createElement("tr");
        
        let typeBadge = "";
        let amountHtml = "";
        
        if (item.type === "Debit") {
            typeBadge = `<span class="status-badge status-expense"><i data-lucide="arrow-down" style="width:12px;height:12px;"></i> Előírás</span>`;
            amountHtml = `<span class="text-danger" style="font-weight:600;">-${formatCurrency(Math.abs(item.amount))}</span>`;
        } else if (item.amount < 0) {
            typeBadge = `<span class="status-badge status-expense"><i data-lucide="arrow-down" style="width:12px;height:12px;"></i> ${(state.currentLang === "en") ? "Correction" : "Korrekció / Jóváírás"}</span>`;
            amountHtml = `<span class="text-danger" style="font-weight:600;">-${formatCurrency(Math.abs(item.amount))}</span>`;
        } else {
            typeBadge = `<span class="status-badge status-verified"><i data-lucide="arrow-up" style="width:12px;height:12px;"></i> ${(state.currentLang === "en") ? "Payment" : "Befizetés"}</span>`;
            amountHtml = `<span class="text-success" style="font-weight:600;">+${formatCurrency(item.amount)}</span>`;
        }
        
        const balanceClass = item.runningBalance < 0 ? "text-danger" : (item.runningBalance > 0 ? "text-success" : "");
        
        row.innerHTML = `
            <td><strong>${item.date}</strong></td>
            <td>${typeBadge}</td>
            <td>${amountHtml}</td>
            <td class="${balanceClass}" style="font-weight:600;">${formatCurrency(item.runningBalance)}</td>
            <td><span style="color:var(--text-muted); font-style:italic;">${item.comment || '-'}</span></td>
        `;
        tbody.appendChild(row);
    });
    if (window.lucide) lucide.createIcons();
}

// 2. Render Admin Dashboard
function renderAdminDashboard() {
    const isEn = (state.currentLang === "en");
    recalculateFlatBalances();
    
    // KPI Cards
    const totalSavings = getBuildingReserve();
    document.getElementById("admin-kpi-balance").textContent = formatCurrency(totalSavings);
    
    const renovationFund = getBuildingRenovationFund();
    document.getElementById("admin-kpi-renovation").textContent = formatCurrency(renovationFund);
    
    const totalArrears = state.flats
        .reduce((sum, f) => {
            const arrA = f.balance < 0 ? Math.abs(f.balance) : 0;
            const arrB = f.renovationBalance < 0 ? Math.abs(f.renovationBalance) : 0;
            return sum + arrA + arrB;
        }, 0);
    document.getElementById("admin-kpi-arrears").textContent = formatCurrency(totalArrears);
    
    const stats = getMonthlyStats();
    const marginEl = document.getElementById("admin-kpi-stats");
    marginEl.textContent = (stats.margin >= 0 ? '+' : '') + formatCurrency(stats.margin);
    if (stats.margin > 0) {
        marginEl.className = "stat-value text-success";
    } else if (stats.margin < 0) {
        marginEl.className = "stat-value text-danger";
    } else {
        marginEl.className = "stat-value";
    }
    document.getElementById("admin-kpi-sub-stats").textContent = isEn ? `Inflow: ${formatCurrency(stats.inflow)} | Outflow: ${formatCurrency(stats.outflow)}` : `Bevétel: ${formatCurrency(stats.inflow)} | Kiadás: ${formatCurrency(stats.outflow)}`;
    
    // Setup select options
    initAdminFormDropdowns();
    
    // Render Arrears Matrix list
    renderArrearsMatrix();
    
    // Render Budget projections
    renderBudgetPlanner();
    
    // Render transactions
    renderAdminTransactions();
}

function initAdminFormDropdowns() {
    const flatSelect = document.getElementById("payment-flat");
    flatSelect.innerHTML = "";
    state.flats.forEach(f => {
        const opt = document.createElement("option");
        opt.value = f.flatNum;
        opt.textContent = (state.currentLang === "en") ? `Flat ${f.flatNum}` : `${f.flatNum}. Lakás`;
        flatSelect.appendChild(opt);
    });
    
    // Add "Egyéb" (Global building level) option
    const otherOpt = document.createElement("option");
    otherOpt.value = "Global";
    otherOpt.textContent = (state.currentLang === "en") ? "Other (Building)" : "Egyéb (Társasház)";
    flatSelect.appendChild(otherOpt);
    
    const today = new Date().toISOString().split('T')[0];
    document.getElementById("payment-date").value = today;
    document.getElementById("expense-date").value = today;
}

