// Delete Transaction
window.quickAddPayment = function(flatNum, type) {
    const flat = state.flats.find(f => f.flatNum === flatNum);
    if (!flat) return;
    const amount = getCurrentFee(flat, type);
    const isEn = (state.currentLang === 'en');
    
    const accountName = type === 'KK' ? (isEn ? "Common Cost" : "Közös Költség") : (isEn ? "Renovation Fund" : "Felújítási Alap");
    
    document.getElementById('quick-pay-flatnum').value = flatNum;
    document.getElementById('quick-pay-type').value = type;
    document.getElementById('quick-pay-amount').value = amount;
    
    document.getElementById('quick-pay-title').textContent = isEn ? "Quick Payment Record" : "Befizetés gyors rögzítése";
    document.getElementById('quick-pay-desc').innerHTML = isEn 
        ? `Do you want to record a payment of <b>${formatCurrency(amount)}</b> to the <b>${accountName}</b> account for <b>Flat ${flatNum}</b>?`
        : `Biztosan rögzíteni szeretnél egy <b>${formatCurrency(amount)}</b> összegű <b>${accountName}</b> befizetést a(z) <b>${flatNum}. lakáshoz</b>?`;
        
    document.getElementById('quick-pay-confirm-modal').style.display = 'flex';
    if (window.lucide) lucide.createIcons();
};

window.confirmQuickPay = function() {
    try {
        const flatNum = document.getElementById('quick-pay-flatnum').value;
        const type = document.getElementById('quick-pay-type').value;
        const amount = parseCleanNumber(document.getElementById('quick-pay-amount').value);
        const isEn = (state.currentLang === 'en');
        
        if (!amount || amount <= 0) {
            alert(isEn ? "Invalid amount" : "Érvénytelen összeg");
            return;
        }
        
        // Close modal immediately for instant UI feedback
        document.getElementById('quick-pay-confirm-modal').style.display = 'none';
        
        const targetAccount = type === 'KK' ? "Közös Költség" : "Felújítási Alap";
        const today = new Date().toISOString().split('T')[0];
        
        const newTx = {
            id: "t-" + Date.now(),
            flatNum: flatNum,
            date: today,
            amount: amount,
            method: "Bank Transfer",
            status: "Verified",
            targetAccount: targetAccount,
            comment: isEn ? "Quick payment" : "Gyors befizetés"
        };
        
        if (!state.transactions) state.transactions = [];
        state.transactions.push(newTx);
        recordItemInVault('transaction', newTx);
        saveStateToLocalStorage();
        recalculateFlatBalances();
        syncStateToCloud();
        playNotificationSound('success');
        renderAdminDashboard();
    } catch (err) {
        console.error("confirmQuickPay error:", err);
        document.getElementById('quick-pay-confirm-modal').style.display = 'none';
        alert("Hiba történt: " + err.message);
    }
};

