window.openEditModal = function(id, type) {
    const modal = document.getElementById("edit-transaction-modal");
    document.getElementById("edit-tx-id").value = id;
    document.getElementById("edit-tx-type").value = type;
    
    const flatGroup = document.getElementById("edit-flat-group");
    const providerGroup = document.getElementById("edit-provider-group");
    const categoryGroup = document.getElementById("edit-category-group");
    const targetAccountGroup = document.getElementById("edit-target-account-group");
    const categorySelect = document.getElementById("edit-tx-category");
    const isEn = (state.currentLang === 'en');
    
    if (type === "Befizetés") {
        flatGroup.style.display = "block";
        providerGroup.style.display = "none";
        categoryGroup.style.display = "none";
        targetAccountGroup.style.display = "block";
        
        const flatSelect = document.getElementById("edit-tx-flat");
        flatSelect.innerHTML = "";
        state.flats.forEach(f => {
            const opt = document.createElement("option");
            opt.value = f.flatNum;
            opt.textContent = isEn ? `Flat ${f.flatNum}` : `${f.flatNum}. Lakás`;
            flatSelect.appendChild(opt);
        });
        const otherOpt = document.createElement("option");
        otherOpt.value = "Global";
        otherOpt.textContent = isEn ? "Other (Building)" : "Egyéb (Társasház)";
        flatSelect.appendChild(otherOpt);
        
        const tx = state.transactions.find(t => t.id === id);
        if (tx) {
            document.getElementById("edit-tx-flat").value = tx.flatNum || "Global";
            document.getElementById("edit-tx-date").value = tx.date;
            document.getElementById("edit-tx-amount").value = tx.amount;
            document.getElementById("edit-tx-target-account").value = tx.targetAccount || "Közös Költség";
            document.getElementById("edit-tx-comment").value = tx.comment || "";
            
            const includeBalanceCheckbox = document.getElementById("edit-tx-include-balance");
            if (includeBalanceCheckbox) {
                includeBalanceCheckbox.checked = tx.includeInBalance !== false;
            }
        }
    } else {
        flatGroup.style.display = "none";
        providerGroup.style.display = "none";
        categoryGroup.style.display = "block";
        targetAccountGroup.style.display = "block";
        
        categorySelect.innerHTML = `
            <option value="Utility">${isEn ? "Utility" : "Közmű"}</option>
            <option value="Insurance">${isEn ? "Insurance" : "Biztosítás"}</option>
            <option value="Maintenance">${isEn ? "Maintenance" : "Karbantartás"}</option>
            <option value="Bank Fee">${isEn ? "Bank Fee" : "Bankköltség"}</option>
            <option value="Other">${isEn ? "Other" : "Egyéb"}</option>
        `;
        
        const exp = state.expenses.find(e => e.id === id);
        if (exp) {
            document.getElementById("edit-tx-target-account").value = exp.targetAccount || (exp.provider === "Felújítási Alap" ? "Felújítási Alap" : "Közös Költség");
            document.getElementById("edit-tx-date").value = exp.date;
            document.getElementById("edit-tx-amount").value = exp.amount;
            categorySelect.value = exp.category || "Other";
            document.getElementById("edit-tx-comment").value = exp.comment || "";
            
            const includeBalanceCheckbox = document.getElementById("edit-tx-include-balance");
            if (includeBalanceCheckbox) {
                includeBalanceCheckbox.checked = exp.includeInBalance !== false;
            }
        }
    }
    
    const includeBalanceGroup = document.getElementById("edit-include-balance-group");
    if (includeBalanceGroup) includeBalanceGroup.style.display = "flex";
    
    // Populate attachments for editing
    const currentTx = (type === "Befizetés" || type === "Payment")
        ? state.transactions.find(t => t.id === id)
        : state.expenses.find(e => e.id === id);
        
    editFormExistingAttachments = (currentTx && currentTx.attachments) 
        ? JSON.parse(JSON.stringify(currentTx.attachments)) 
        : ((currentTx && currentTx.attachment) ? [JSON.parse(JSON.stringify(currentTx.attachment))] : []);
    editFormNewAttachments = [];
    const editFileInput = document.getElementById("edit-tx-attachment-file");
    if (editFileInput) editFileInput.value = "";
    renderEditExistingAttachments();
    renderEditNewAttachments();
    
    modal.style.display = "flex";
};

