// Submit handler for Flat Common Cost Edit form (handling dual cost updates)
document.getElementById("flat-fee-edit-form").addEventListener("submit", function(e) {
    e.preventDefault();
    
    const flatNum = document.getElementById("flat-detail-flatnum-hidden").value;
    const newOwnerName = document.getElementById("flat-owner-input").value.trim();
    const newPhone = document.getElementById("flat-phone-input").value.trim();
    const newEmail = (document.getElementById("flat-email-input")?.value || "").trim();
    const newOwnershipShare = parseFloat(document.getElementById("flat-ownership-input").value) || 0;
    const newTenantCount = parseInt(document.getElementById("flat-tenant-input").value) || 1;
    
    const newFee = parseFloat(document.getElementById("flat-edit-fee-a").value) || 0;
    const newFeeDate = document.getElementById("flat-edit-fee-date-a").value;
    
    const newRenovationFee = parseFloat(document.getElementById("flat-edit-fee-b").value) || 0;
    const newRenovationFeeDate = document.getElementById("flat-edit-fee-date-b").value;
    
    const flatIndex = state.flats.findIndex(f => f.flatNum === flatNum);
    if (flatIndex === -1) return;
    const flat = state.flats[flatIndex];
    
    // 1. Process Fee Changes First
    const todayDateObj = new Date();
    
    if (newFeeDate) {
        if (!flat.feeChangesKK) flat.feeChangesKK = [];
        const formattedDate = newFeeDate + "-01";
        // Visszamenőleges módosítás: Törlünk minden olyan szabályt, ami az új dátummal azonos vagy annál későbbi, 
        // így garantáltan ez lesz az új végleges díj a megadott hónaptól kezdve (a jelenre is kihatva).
        flat.feeChangesKK = flat.feeChangesKK.filter(c => new Date(c.date) < new Date(formattedDate));
        flat.feeChangesKK.push({ date: formattedDate, amount: newFee });
    } else {
        if (flat.feeChangesKK && flat.feeChangesKK.length > 0) {
            const activeChanges = flat.feeChangesKK.filter(c => new Date(c.date) <= todayDateObj);
            if (activeChanges.length > 0) {
                activeChanges.sort((a, b) => new Date(b.date) - new Date(a.date));
                activeChanges[0].amount = newFee;
            } else {
                flat.monthlyFee = newFee;
            }
        } else {
            flat.monthlyFee = newFee; 
        }
    }
    
    if (newRenovationFeeDate) {
        if (!flat.feeChangesFA) flat.feeChangesFA = [];
        const formattedDate = newRenovationFeeDate + "-01";
        flat.feeChangesFA = flat.feeChangesFA.filter(c => new Date(c.date) < new Date(formattedDate));
        flat.feeChangesFA.push({ date: formattedDate, amount: newRenovationFee });
    } else {
        if (flat.feeChangesFA && flat.feeChangesFA.length > 0) {
            const activeChanges = flat.feeChangesFA.filter(c => new Date(c.date) <= todayDateObj);
            if (activeChanges.length > 0) {
                activeChanges.sort((a, b) => new Date(b.date) - new Date(a.date));
                activeChanges[0].amount = newRenovationFee;
            } else {
                flat.renovationFee = newRenovationFee;
            }
        } else {
            flat.renovationFee = newRenovationFee;
        }
    }
    
    flat.ownershipShare = newOwnershipShare;
    flat.tenantCount = newTenantCount;
    
    flat.email = newEmail;
    flat.ownerName = newOwnerName;
    
    let user = state.users.find(u => (u.flatNum === flatNum && (u.buildingId === state.currentBuildingId || !u.buildingId)) || u.id === flatNum);
    if (user) {
        if (newOwnerName) user.name = newOwnerName;
        user.phone = newPhone;
        if (newEmail) user.email = newEmail;
    } else {
        state.users.push({
            id: "u-" + Date.now(),
            email: newEmail,
            name: newOwnerName,
            role: "Owner",
            flatNum: flatNum,
            buildingId: state.currentBuildingId,
            pass: "lakas123"
        });
    }
    
    // 2. Process Manual Balance Overrides (silently adjust baseline without creating transactions in history)
    const balAInput = document.getElementById("flat-edit-balance-a");
    const targetBalA = balAInput ? parseFloat(balAInput.value) || 0 : (flat.balance || 0);
    const originalBalA = balAInput ? parseFloat(balAInput.dataset.original) || 0 : (flat.balance || 0);
    
    const balBInput = document.getElementById("flat-edit-balance-b");
    const targetBalB = balBInput ? parseFloat(balBInput.value) || 0 : (flat.renovationBalance || 0);
    const originalBalB = balBInput ? parseFloat(balBInput.dataset.original) || 0 : (flat.renovationBalance || 0);
    
    if (targetBalA !== originalBalA) {
        const timelineA = getFlatLedgerTimeline(flat.flatNum, "Közös Költség");
        const txSumA = timelineA.reduce((sum, item) => sum + item.amount, 0);
        flat.initialBalance = targetBalA - txSumA;
        flat.balance = targetBalA;
    }
    
    if (targetBalB !== originalBalB) {
        const timelineB = getFlatLedgerTimeline(flat.flatNum, "Felújítási Alap");
        const txSumB = timelineB.reduce((sum, item) => sum + item.amount, 0);
        flat.initialRenovationBalance = targetBalB - txSumB;
        flat.renovationBalance = targetBalB;
    }
    
    // Clean up any historical "Correction" items from state.transactions so history stays 100% clean
    if (state.transactions) {
        state.transactions = state.transactions.filter(t => t.type !== "Correction" && t.method !== "Egyenleg korrekció");
    }
    
    recalculateFlatBalances();
    recordItemInVault('flatOverride', flat);
    saveStateToLocalStorage();
    syncStateToCloud();
    
    window.openFlatDetailModal(flatNum);
    renderAdminDashboard();
    playNotificationSound('success');
});

