document.getElementById("add-flat-form").addEventListener("submit", function(e) {
    e.preventDefault();
    const flatNum = document.getElementById("new-flat-num").value.trim();
    const ownerName = document.getElementById("new-flat-owner").value.trim();
    const email = (document.getElementById("new-flat-email")?.value || "").trim();
    const pass = "lakas123";
    const monthlyFee = parseInt(document.getElementById("new-flat-monthly").value, 10);
    const renovationFee = parseInt(document.getElementById("new-flat-renovation").value, 10);
    const ownershipShare = parseFloat(document.getElementById("new-flat-ownership").value) || 0;
    const areaVal = parseFloat(document.getElementById("new-flat-area")?.value) || 0;
    const terraceVal = parseFloat(document.getElementById("new-flat-terrace")?.value) || 0;
    const garageStr = (document.getElementById("new-flat-garage")?.value || "").trim();
    const garageMatches = garageStr.match(/\d+(?:[.,]\d+)?/g);
    const newGarages = garageMatches ? garageMatches.map(m => parseFloat(m.replace(',', '.'))).filter(a => a > 0) : [];
    const tenantCount = parseInt(document.getElementById("new-flat-tenant").value, 10) || 1;
    
    if (state.flats.some(f => f.flatNum === flatNum)) {
        showToast(isEn ? "This flat number already exists in this building!" : "Ez a lakásszám már létezik ebben a társasházban!", 'alert-circle', '#ef4444');
        return;
    }
    
    state.flats.push({
        flatNum,
        ownerName,
        email,
        tenantCount,
        ownershipShare,
        area: areaVal,
        terraceArea: terraceVal,
        balconyArea: terraceVal,
        garages: newGarages,
        garageNum: newGarages.length > 0 ? newGarages.map(g => `${g} m²`).join(', ') : '',
        monthlyFee,
        renovationFee,
        balance: 0,
        renovationBalance: 0
    });
    
    // Check if user with this email already exists
    let existingUser = state.users.find(u => u.email && u.email.toLowerCase() === email.toLowerCase());
    if (!existingUser) {
        state.users.push({
            id: "u-" + Date.now(),
            email: email,
            name: ownerName,
            role: "Owner",
            flatNum: flatNum,
            buildingId: state.currentBuildingId,
            pass: pass
        });
    }
    
    saveStateToLocalStorage();
    closeAddFlatModal();
    renderAdminDashboard();
    playNotificationSound('success');
});

function openDeleteModal(flatNum) {
    document.getElementById("delete-flat-num-hidden").value = flatNum;
    document.getElementById("delete-confirm-modal").style.display = "flex";
}
window.openDeleteModal = openDeleteModal;

function closeDeleteModal() {
    document.getElementById("delete-confirm-modal").style.display = "none";
}
window.closeDeleteModal = closeDeleteModal;

function confirmDeleteFlat() {
    const flatNum = (document.getElementById("delete-flat-num-hidden")?.value || "").trim();
    if (!flatNum) return;
    
    const vault = getPermanentVault();
    vault.deletedFlatNums = vault.deletedFlatNums || [];
    if (!vault.deletedFlatNums.includes(flatNum)) {
        vault.deletedFlatNums.push(flatNum);
    }
    if (vault.flatOverrides && vault.flatOverrides[flatNum]) {
        delete vault.flatOverrides[flatNum];
    }
    savePermanentVault(vault);
    
    (state.buildings || []).forEach(b => {
        if (b.flats) {
            b.flats = b.flats.filter(f => f.flatNum && f.flatNum.trim() !== flatNum);
        }
    });
    state.flats = (state.flats || []).filter(f => f.flatNum && f.flatNum.trim() !== flatNum);
    state.users = (state.users || []).filter(u => u.flatNum && u.flatNum.trim() !== flatNum);
    
    saveStateToLocalStorage();
    syncStateToCloud();
    closeDeleteModal();
    renderAdminDashboard();
}
window.confirmDeleteFlat = confirmDeleteFlat;

function openGlobalBalancesModal() {
    document.getElementById("global-start-common").value = getBuildingReserve();
    document.getElementById("global-start-renovation").value = getBuildingRenovationFund();
    document.getElementById("global-balances-modal").style.display = "flex";
}
window.openGlobalBalancesModal = openGlobalBalancesModal;

function closeGlobalBalancesModal() {
    document.getElementById("global-balances-modal").style.display = "none";
}
window.closeGlobalBalancesModal = closeGlobalBalancesModal;

document.getElementById("global-balances-form").addEventListener("submit", function(e) {
    e.preventDefault();
    try {
        const desiredCommon = parseCleanNumber(document.getElementById("global-start-common").value);
        const desiredReno = parseCleanNumber(document.getElementById("global-start-renovation").value);
        
        // Close modal immediately for instant UI feedback
        closeGlobalBalancesModal();
        
        // Common Cost Net calculation matching getBuildingReserve() filter exactly
        const totalPayments = (state.transactions || [])
            .filter(tx => tx.status === "Verified" && (tx.targetAccount === "Közös Költség" || (!tx.targetAccount && tx.targetAccount !== "Felújítási Alap")) && tx.includeInBalance !== false)
            .reduce((sum, tx) => sum + (tx.amount || 0), 0);
        const totalExpenses = (state.expenses || [])
            .filter(exp => (exp.targetAccount === "Közös Költség" || (!exp.targetAccount && exp.provider !== "Felújítási Alap")) && exp.includeInBalance !== false)
            .reduce((sum, exp) => sum + (exp.amount || 0), 0);
        const currentNetCommon = totalPayments - totalExpenses;
        state.buildingInitialReserveCommon = desiredCommon - currentNetCommon;
        
        // Renovation Fund Net calculation matching getBuildingRenovationFund() filter exactly
        const totalRenovationPayments = (state.transactions || [])
            .filter(tx => tx.status === "Verified" && tx.targetAccount === "Felújítási Alap" && tx.includeInBalance !== false)
            .reduce((sum, tx) => sum + (tx.amount || 0), 0);
        const totalRenovationExpenses = (state.expenses || [])
            .filter(exp => (exp.targetAccount === "Felújítási Alap" || (!exp.targetAccount && exp.provider === "Felújítási Alap")) && exp.includeInBalance !== false)
            .reduce((sum, exp) => sum + (exp.amount || 0), 0);
        const currentNetReno = totalRenovationPayments - totalRenovationExpenses;
        state.buildingInitialReserveRenovation = desiredReno - currentNetReno;
        
        saveStateToLocalStorage();
        renderAdminDashboard();
    } catch (err) {
        console.error("Global balances form error:", err);
        closeGlobalBalancesModal();
        alert("Hiba történt: " + err.message);
    }
});

// Fullscreen state vars
let fullscreenEditMode = false;
let fullscreenType = null;
let flatTimelineEditMode = false;
let fullscreenSearchQuery = '';

function renderFullscreenList() {
    const tbody = document.getElementById("fullscreen-tx-tbody");
    if (!tbody) return;
    tbody.innerHTML = "";
    
    const isEn = (state.currentLang === 'en');
    
    if (fullscreenType === 'flat') {
        const flatNum = state.currentFlatDetailNum;
        const timeline = getCombinedFlatLedgerTimeline(flatNum);
        // Sort chronologically descending (newest on top)
        let items = [...timeline].sort((a, b) => {
            const diff = new Date(b.date) - new Date(a.date);
            if (diff !== 0) return diff;
            return (b.id || '').localeCompare(a.id || '');
        });
        
        if (fullscreenSearchQuery) {
            const q = fullscreenSearchQuery.toLowerCase();
            items = items.filter(item =>
                item.date.includes(q) ||
                (item.method && item.method.toLowerCase().includes(q)) ||
                (item.account && item.account.toLowerCase().includes(q)) ||
                (item.comment && item.comment.toLowerCase().includes(q)) ||
                formatCurrency(Math.abs(item.amount)).includes(q)
            );
        }
        
        if (items.length === 0) {
            tbody.innerHTML = `<div style="padding:80px 24px; text-align:center; color:var(--text-muted); display:flex; flex-direction:column; align-items:center; justify-content:center; gap:12px; min-height:520px;">
        <i data-lucide="search-x" style="width:40px;height:40px;opacity:0.4;"></i>
        <div style="font-size:15px; font-weight:500;">Nem található tranzakció</div>
        <div style="font-size:13px; opacity:0.8;">Próbálj meg más keresési kifejezést beírni!</div>
    </div>`;
            if (window.lucide) lucide.createIcons();
            return;
        }
        
        items.forEach(item => {
            const itemEl = document.createElement("div");
            itemEl.className = "tx-item";
            
            const isDemand = item.type === "Debit";
            const isNegative = isDemand || item.amount < 0;
            const iconClass = isNegative ? "expense" : "income";
            const iconName = isNegative ? "minus" : "plus";
            const amountColor = isNegative ? "var(--danger)" : "var(--success)";
            const amountFormatted = isNegative ? `-${formatCurrency(Math.abs(item.amount))}` : `+${formatCurrency(item.amount)}`;
            
            const actionsHtml = fullscreenEditMode ? `
                <div class="tx-actions">
                    <button class="btn btn-outline btn-sm btn-icon-only" style="border:none; padding:4px;" onclick="${item.id ? `openEditModal('${item.id}', 'Befizetés')` : `openFullscreenCommentEdit('${flatNum}', '${item.date}', '${item.type}', '${item.account}', '')`}" title="${isEn ? "Edit" : "Módosítás"}">
                        <i data-lucide="edit-3" style="width:16px;height:16px;"></i>
                    </button>
                    <button class="btn btn-outline btn-sm btn-icon-only" style="border:none; color:var(--danger); padding:4px;" onclick="deleteFlatLedgerTx('${item.id || ''}', '${flatNum}', '${item.date}', '${item.account}')" title="${isEn ? "Delete" : "Törlés"}">
                        <i data-lucide="trash-2" style="width:16px;height:16px;"></i>
                    </button>
                </div>
            ` : '';
            
            const commentHtml = `
                <div style="margin-top: 5px; display: flex; align-items: center; gap: 6px; flex-wrap:wrap;">
                    ${item.comment
                        ? `<span style="font-size:12px; color:var(--text-muted); font-style:italic;">💬 ${item.comment}</span>`
                        : `<span style="font-size:11px; color:var(--border-color);">–</span>`}
                    <button class="btn btn-outline btn-sm btn-icon-only" style="border:none; padding:2px; height:auto; background:transparent; flex-shrink:0;" onclick="openFullscreenCommentEdit('${flatNum}', '${item.date}', '${item.type}', '${item.account}', '${item.id || ''}')" title="${isEn ? "Edit comment" : "Megjegyzés szerkesztése"}">
                        <i data-lucide="pencil-line" style="width:12px;height:12px;color:var(--primary)"></i>
                    </button>
                </div>
            `;
            
            const attsHtml = renderTxAttachmentsHtml(item);
            itemEl.innerHTML = `
                <div class="tx-icon ${iconClass}"><i data-lucide="${iconName}" style="width:14px;height:14px;"></i></div>
                <div class="tx-details" style="flex: 1;">
                    <div class="tx-date">${item.date}${item.account ? ' • ' + item.account : ''}</div>
                    <div class="tx-method">${item.method || (isDemand ? 'Havi Előírás' : 'Befizetés')}</div>
                    ${item.reference ? `<div class="tx-desc">${item.reference}</div>` : ''}
                    ${commentHtml}
                    ${attsHtml}
                </div>
                <div class="tx-amounts">
                    <div class="tx-amount" style="color: ${amountColor};">${amountFormatted}</div>
                </div>
                ${actionsHtml}
            `;
            tbody.appendChild(itemEl);
        });
        
    } else if (fullscreenType === 'global') {
        const isEn = (state.currentLang === 'en');
        const paymentsList = state.transactions.map(t => {
            const isGlobal = (t.flatNum === 'Global' || t.flatNum === 'Egyéb' || !t.flatNum);
            const desc = t.description || t.title || t.payerName || '';
            const name = isGlobal 
                ? (desc || (isEn ? "Other (Building)" : "Egyéb (Társasház)"))
                : (isEn ? `Flat ${t.flatNum}` : `${t.flatNum}. Lakás`);
            return {
                ...t,
                itemType: "Befizetés",
                displayName: name,
                categoryDisplay: t.targetAccount === "Közös Költség" ? (isEn ? "Common Cost" : "Közös Költség") : (isEn ? "Renovation Fund" : "Felújítási Alap"),
                amountDisplay: t.amount < 0 ? `-${formatCurrency(Math.abs(t.amount))}` : `+${formatCurrency(t.amount)}`,
                icon: t.targetAccount === "Közös Költség" ? "check" : "piggy-bank",
                note: (t.comment && t.comment !== desc) ? t.comment : (!isGlobal ? desc : '')
            };
        });
        
        const expensesList = state.expenses.map(e => ({
            ...e,
            itemType: "Kiadás",
            displayName: e.provider || (isEn ? "Expense" : "Kiadás"),
            categoryDisplay: translateCategory(e.category),
            amountDisplay: `-${formatCurrency(e.amount)}`,
            icon: "minus",
            note: e.description || e.comment || ''
        }));
        
        // Sort chronologically descending (newest on top)
        let combined = [...paymentsList, ...expensesList].sort((a, b) => {
            const diff = new Date(b.date || 0) - new Date(a.date || 0);
            if (diff !== 0) return diff;
            return (b.id || '').localeCompare(a.id || '');
        });
        
        if (fullscreenSearchQuery) {
            const q = fullscreenSearchQuery.toLowerCase();
            combined = combined.filter(item =>
                (item.date || '').includes(q) ||
                (item.displayName || '').toLowerCase().includes(q) ||
                (item.categoryDisplay || '').toLowerCase().includes(q) ||
                (item.amountDisplay || '').includes(q) ||
                (item.note || '').toLowerCase().includes(q) ||
                (item.description || '').toLowerCase().includes(q) ||
                (item.comment && item.comment.toLowerCase().includes(q))
            );
        }
        
        if (combined.length === 0) {
            tbody.innerHTML = `<div style="padding:80px 24px; text-align:center; color:var(--text-muted); display:flex; flex-direction:column; align-items:center; justify-content:center; gap:12px; min-height:520px;">
        <i data-lucide="search-x" style="width:40px;height:40px;opacity:0.4;"></i>
        <div style="font-size:15px; font-weight:500;">${isEn ? "No transactions found" : "Nem található tranzakció"}</div>
        <div style="font-size:13px; opacity:0.8;">${isEn ? "Try searching with a different term!" : "Próbálj meg más keresési kifejezést beírni!"}</div>
    </div>`;
            if (window.lucide) lucide.createIcons();
            return;
        }
        
        combined.forEach(item => {
            const itemEl = document.createElement("div");
            itemEl.className = "tx-item";
            
            const iconClass = item.itemType === "Befizetés" ? "income" : "expense";
            
            const actionsHtml = fullscreenEditMode ? `
                <div class="tx-actions">
                    <button class="btn btn-outline btn-sm btn-icon-only" style="border:none; padding:4px;" onclick="openEditModal('${item.id}', '${item.itemType}')" title="Módosítás">
                        <i data-lucide="edit-3" style="width:16px;height:16px;"></i>
                    </button>
                    <button class="btn btn-outline btn-sm btn-icon-only" style="border:none; color:var(--danger); padding:4px;" onclick="deleteTransaction('${item.id}', '${item.itemType}')" title="Törlés">
                        <i data-lucide="trash-2" style="width:16px;height:16px;"></i>
                    </button>
                </div>
            ` : '';
            
            const attsHtml = renderTxAttachmentsHtml(item);
            
            itemEl.innerHTML = `
                <div class="tx-icon ${iconClass}"><i data-lucide="${item.icon}" style="width:18px;height:18px;"></i></div>
                <div class="tx-details">
                    <div class="tx-title">${item.displayName}</div>
                    <div class="tx-subtitle">${item.date} • ${item.categoryDisplay}${item.note ? ' • ' + item.note : ''}</div>
                    ${attsHtml}
                </div>
                <div class="tx-amount-group">
                    <div class="tx-amount ${item.itemType === 'Befizetés' ? 'positive' : 'negative'}">${item.amountDisplay}</div>
                </div>
                ${actionsHtml}
            `;
            tbody.appendChild(itemEl);
        });
    }
    
    if (window.lucide) lucide.createIcons();
}


