window.exportFullscreenToExcel = function() {
    if (!window.XLSX) { alert('Excel exportáló nem elérhető.'); return; }
    if (fullscreenType === 'flat') {
        exportFlatDetailToExcel();
    } else {
        exportTransactionsToExcel();
    }
};

window.exportFlatLedgerToExcel = function(account) {
    if (!window.XLSX) { alert('Excel exportáló nem elérhető.'); return; }
    const flatNum = state.currentUser && state.currentUser.flatNum;
    if (!flatNum) return;
    const accountName = account === 'A' ? 'Közös Költség' : 'Felújítási Alap';
    const timeline = getFlatLedgerTimeline(flatNum, accountName).slice().reverse();
    const data = timeline.map(item => ({
        'Dátum': item.date,
        'Típus': item.type === 'Debit' ? 'Előírás' : 'Befizetés',
        'Összeg': item.amount,
        'Egyenleg': item.runningBalance,
        'Megjegyzés': item.comment || ''
    }));
    const ws = XLSX.utils.json_to_sheet(data);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, accountName.substring(0, 31));
    XLSX.writeFile(wb, `${flatNum}_${accountName.replace(/\s/g,'_')}.xlsx`);
};

window.exportCombinedFlatLedgerToExcel = function() {
    if (!window.XLSX) { alert('Excel exportáló nem elérhető.'); return; }
    const flatNum = state.currentUser && state.currentUser.flatNum;
    if (!flatNum) return;
    const timelineKK = getFlatLedgerTimeline(flatNum, 'Közös Költség');
    const timelineFA = getFlatLedgerTimeline(flatNum, 'Felújítási Alap');
    const combined = [
        ...timelineKK.map(item => ({ ...item, account: 'Közös Költség' })),
        ...timelineFA.map(item => ({ ...item, account: 'Felújítási Alap' }))
    ].sort((a, b) => new Date(a.date) - new Date(b.date));
    const data = combined.map(item => ({
        'Dátum': item.date,
        'Számla': item.account,
        'Típus': item.type === 'Debit' ? 'Előírás' : 'Befizetés',
        'Összeg': item.amount,
        'Megjegyzés': item.comment || ''
    }));
    const ws = XLSX.utils.json_to_sheet(data);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, 'Tranzakciók');
    XLSX.writeFile(wb, `${flatNum}_Tranzakciok.xlsx`);
};

