// Bind form submit on DOMContentLoaded
window.addEventListener("DOMContentLoaded", () => {
    const form = document.getElementById("flat-detail-add-tx-form");
    if (form) {
        form.addEventListener("submit", function(e) {
            e.preventDefault();
            const flatNum = state.currentFlatDetailNum;
            if (!flatNum) return;
            
            const type = document.getElementById("flat-add-tx-type").value;
            const account = document.getElementById("flat-add-tx-account").value;
            const date = document.getElementById("flat-add-tx-date").value;
            const amount = parseInt(document.getElementById("flat-add-tx-amount").value, 10);
            const comment = document.getElementById("flat-add-tx-comment").value.trim();
            const categorySelect = document.getElementById("flat-add-tx-category");
            const categoryVal = categorySelect ? categorySelect.value : (type === "Befizetés" ? "Bank Transfer" : "Other");
            const isEn = (state.currentLang === 'en');
            const includeInBalance = document.getElementById("flat-add-tx-include-balance").checked;
            const attachmentsToSave = [...flatAddFormAttachments];
            
            if (flatNum === "Global") {
                if (type === "Befizetés") {
                    const newTx = {
                        id: "t-" + Date.now(),
                        flatNum: "Global",
                        date: date,
                        amount: amount,
                        method: categoryVal,
                        status: "Verified",
                        targetAccount: account,
                        comment: comment || (isEn ? "Global Income" : "Közös bevétel"),
                        includeInBalance: includeInBalance,
                        attachments: attachmentsToSave
                    };
                    state.transactions.push(newTx);
                } else {
                    // Terhelés on building level goes into expenses as building cost
                    const newExpense = {
                        id: "e-" + Date.now(),
                        date: date,
                        category: categoryVal,
                        provider: account,
                        targetAccount: account,
                        amount: amount,
                        comment: comment || (account === "Közös Költség" ? "Közös Költség kiadás" : "Felújítási Alap kiadás"),
                        includeInBalance: includeInBalance,
                        attachments: attachmentsToSave
                    };
                    state.expenses.push(newExpense);
                }
                
                saveStateToLocalStorage();
                recalculateFlatBalances();
                syncStateToCloud();
                playNotificationSound('success');
                
                document.getElementById("flat-add-tx-include-balance").checked = true;
                flatAddFormAttachments = [];
                const flatFileInput = document.getElementById("flat-add-attachment-file");
                if (flatFileInput) flatFileInput.value = "";
                renderFlatAddAttachmentList();
                closeFlatDetailAddTxModal();
                renderAdminDashboard(); // Refresh main view
            } else {
                if (type === "Befizetés") {
                    const newTx = {
                        id: "t-" + Date.now(),
                        flatNum: flatNum,
                        date: date,
                        amount: amount,
                        method: categoryVal,
                        status: "Verified",
                        targetAccount: account,
                        comment: comment || (isEn ? "Payment" : "Befizetés"),
                        includeInBalance: includeInBalance,
                        attachments: attachmentsToSave
                    };
                    state.transactions.push(newTx);
                } else {
                    // Terhelés (Debit) goes into manualDebits so it doesn't affect building reserve pool
                    const newDebit = {
                        id: "d-manual-" + Date.now(),
                        flatNum: flatNum,
                        date: date,
                        amount: amount,
                        targetAccount: account,
                        category: categoryVal,
                        comment: comment || (isEn ? "Debit charge" : "Terhelés"),
                        includeInBalance: includeInBalance,
                        attachments: attachmentsToSave
                    };
                    state.manualDebits.push(newDebit);
                }
                
                saveStateToLocalStorage();
                recalculateFlatBalances();
                syncStateToCloud();
                playNotificationSound('success');
                
                document.getElementById("flat-add-tx-include-balance").checked = true;
                flatAddFormAttachments = [];
                const flatFileInput = document.getElementById("flat-add-attachment-file");
                if (flatFileInput) flatFileInput.value = "";
                renderFlatAddAttachmentList();
                closeFlatDetailAddTxModal();
                openFlatDetailModal(flatNum); // Refresh detail modal
                renderAdminDashboard(); // Refresh main view
            }
        });
    }
});

