window.showToast = function(msg, icon = 'check-circle-2', color = '#10b981') {
    let toast = document.getElementById("global-copy-toast");
    if (!toast) {
        toast = document.createElement("div");
        toast.id = "global-copy-toast";
        toast.style.cssText = `
            position: fixed;
            top: 24px;
            left: 50%;
            transform: translateX(-50%) translateY(-20px);
            background: rgba(15, 23, 42, 0.94);
            color: #ffffff;
            padding: 12px 24px;
            border-radius: 9999px;
            font-size: 14px;
            font-weight: 600;
            display: flex;
            align-items: center;
            gap: 10px;
            box-shadow: 0 12px 35px rgba(0,0,0,0.35);
            z-index: 9999999;
            opacity: 0;
            transition: opacity 0.28s cubic-bezier(0.16, 1, 0.3, 1), transform 0.28s cubic-bezier(0.16, 1, 0.3, 1);
            pointer-events: none;
            backdrop-filter: blur(12px);
            -webkit-backdrop-filter: blur(12px);
            border: 1px solid rgba(255,255,255,0.15);
            max-width: 90vw;
            text-align: center;
            box-sizing: border-box;
        `;
        document.body.appendChild(toast);
    }
    
    const isEn = (state.currentLang === 'en');
    toast.innerHTML = `<i data-lucide="${icon}" style="width:18px;height:18px;color:${color};flex-shrink:0;"></i> <span>${msg || (isEn ? 'Saved successfully!' : 'Sikeres mentés!')}</span>`;
    if (window.lucide) lucide.createIcons();
    
    // Animate in
    toast.style.opacity = "1";
    toast.style.transform = "translateX(-50%) translateY(0)";
    
    if (window._toastTimeout) clearTimeout(window._toastTimeout);
    window._toastTimeout = setTimeout(() => {
        toast.style.opacity = "0";
        toast.style.transform = "translateX(-50%) translateY(-20px)";
    }, 2800);
};

window.copyValue = function(val, btnElement) {
    const isEn = (state.currentLang === 'en');
    navigator.clipboard.writeText(val).then(() => {
        showToast(isEn ? "Copied!" : "Másolva!");
        if (btnElement) {
            const origHtml = btnElement.innerHTML;
            btnElement.innerHTML = '<i data-lucide="check" style="width:12px;height:12px;color:var(--success);"></i>';
            if (window.lucide) lucide.createIcons();
            setTimeout(() => {
                btnElement.innerHTML = origHtml;
                if (window.lucide) lucide.createIcons();
            }, 1800);
        }
    }).catch(() => {
        showToast(isEn ? "Copied!" : "Másolva!");
    });
};

