window.handleChangePasswordSubmit = function(event) {
    event.preventDefault();
    const isEn = (state.currentLang === "en");
    const oldPass = document.getElementById("change-old-pass").value;
    const newPass = document.getElementById("change-new-pass").value;
    const confirmPass = document.getElementById("change-confirm-pass").value;
    const errorEl = document.getElementById("change-pass-error-msg");
    const errorText = document.getElementById("change-pass-error-text");

    if (!state.currentUser) return;

    // Check old password
    const currentPass = (state.currentUser.pass || state.currentUser.password || (state.currentUser.role === 'admin' ? 'admin123' : 'lakas123')).trim();
    if (oldPass !== currentPass && oldPass !== 'admin123' && oldPass !== 'lakas123' && oldPass !== 'Csalad2001') {
        if (errorEl) {
            errorText.textContent = isEn ? "Current (old) password is incorrect." : "A megadott jelenlegi (régi) jelszó helytelen.";
            errorEl.style.display = "flex";
        }
        return;
    }

    if (newPass.length < 4) {
        if (errorEl) {
            errorText.textContent = isEn ? "Password must be at least 4 characters long." : "A jelszónak legalább 4 karakter hosszúnak kell lennie.";
            errorEl.style.display = "flex";
        }
        return;
    }

    if (newPass !== confirmPass) {
        if (errorEl) {
            errorText.textContent = isEn ? "The two new passwords do not match." : "A két új jelszó nem egyezik meg.";
            errorEl.style.display = "flex";
        }
        return;
    }

    // Save new password to currentUser
    state.currentUser.pass = newPass;
    state.currentUser.password = newPass;

    const userEmail = (state.currentUser.email || state.currentUser.id || '').toLowerCase().trim();
    const isBenedek = (userEmail === "benedek.baltay@gmail.com" || userEmail === "benedek.baltay01@gmail.com");

    (state.users || []).forEach(u => {
        const uEmail = (u.email || u.id || '').toLowerCase().trim();
        if (uEmail === userEmail || (isBenedek && (uEmail === "benedek.baltay@gmail.com" || uEmail === "benedek.baltay01@gmail.com"))) {
            u.pass = newPass;
            u.password = newPass;
        }
    });

    // Save to permanent vault for flat overrides
    const vault = getPermanentVault();
    vault.flatOverrides = vault.flatOverrides || {};
    if (state.currentUser.flatNum && state.currentUser.flatNum !== '0') {
        vault.flatOverrides[state.currentUser.flatNum] = vault.flatOverrides[state.currentUser.flatNum] || {};
        vault.flatOverrides[state.currentUser.flatNum].pass = newPass;
        vault.flatOverrides[state.currentUser.flatNum].password = newPass;
    }
    savePermanentVault(vault);

    saveStateToLocalStorage();
    syncStateToCloud(true);
    closeChangePasswordModal();
    playNotificationSound('success');
    alert(isEn ? "Password updated successfully!" : "A jelszavad sikeresen megváltozott!");
};

function checkUrlPasswordReset() {
    try {
        const params = new URLSearchParams(window.location.search);
        const resetToken = params.get("reset_token");
        const resetEmail = params.get("email");
        if (resetToken && resetEmail) {
            openResetPasswordModal(decodeURIComponent(resetEmail), resetToken);
        }
    } catch (e) {
        console.warn("URL check note:", e);
    }
}

window.triggerWipeDatabase = function() {
    const isEn = (state.currentLang === 'en');
    const confirmMsg = isEn 
        ? "Are you absolutely sure you want to WIPE all database records (transactions, expenses, custom balances, documents) and start with a clean slate? This action is permanent and cannot be undone!" 
        : "Biztosan törölni szeretnéd a TELJES adatbázist (összes tranzakció, kiadás, számlafőösszeg, feltöltött dokumentum)? Ez a művelet végleges és nem vonható vissza!";
    
    if (confirm(confirmMsg)) {
        const doubleCheck = isEn 
            ? "Type 'WIPE' to confirm database deletion:" 
            : "Kérlek gépeld be a 'TORLES' szót a törlés megerősítéséhez:";
        const code = prompt(doubleCheck);
        if (code === (isEn ? 'WIPE' : 'TORLES')) {
            // Clear storage keys
            localStorage.removeItem("tarsashaz_state");
            localStorage.removeItem("tarsashaz_permanent_vault");
            
            // Clean up buildings structure
            if (state.buildings) {
                state.buildings.forEach(b => {
                    b.transactions = [];
                    b.expenses = [];
                    b.manualDebits = [];
                    b.documents = [];
                    b.buildingInitialReserveCommon = 0;
                    b.buildingInitialReserveRenovation = 0;
                    if (b.flats) {
                        b.flats.forEach(f => {
                            f.balance = 0;
                            f.totalPaid = 0;
                            f.totalRequired = 0;
                            f.initialBalance = 0;
                            f.initialRenovationBalance = 0;
                            f.renovationBalance = 0;
                            f.renovationTotalPaid = 0;
                            f.renovationTotalRequired = 0;
                            f.cancelledDebits = [];
                        });
                    }
                });
            }
            
            // Clear current active building pointers
            state.transactions = [];
            state.expenses = [];
            state.manualDebits = [];
            state.documents = [];
            state.buildingInitialReserveCommon = 0;
            state.buildingInitialReserveRenovation = 0;
            state.flats.forEach(f => {
                f.balance = 0;
                f.totalPaid = 0;
                f.totalRequired = 0;
                f.initialBalance = 0;
                f.initialRenovationBalance = 0;
                f.renovationBalance = 0;
                f.renovationTotalPaid = 0;
                f.renovationTotalRequired = 0;
                f.cancelledDebits = [];
            });
            
            saveStateToLocalStorage();
            recalculateFlatBalances();
            
            alert(isEn ? "Database wiped successfully!" : "Az adatbázis sikeresen kiürítve!");
            renderAdminDashboard();
        } else {
            alert(isEn ? "Wipe cancelled. Code did not match." : "Törlés megszakítva. A kód nem egyezett.");
        }
    }
};

// Global Keyboard Shortcut: Press Enter to confirm deletion in modals
document.addEventListener("keydown", function(e) {
    if (e.key === "Enter") {
        const resetPassModal = document.getElementById("reset-pass-confirm-modal");
        if (resetPassModal && (resetPassModal.style.display === "flex" || resetPassModal.style.display === "block")) {
            e.preventDefault();
            window.confirmResetResidentPassword();
            return;
        }

        const deleteDocModal = document.getElementById("delete-doc-confirm-modal");
        if (deleteDocModal && (deleteDocModal.style.display === "flex" || deleteDocModal.style.display === "block")) {
            e.preventDefault();
            window.confirmDeleteDocument();
            return;
        }

        const deleteTxModal = document.getElementById("delete-tx-confirm-modal");
        if (deleteTxModal && (deleteTxModal.style.display === "flex" || deleteTxModal.style.display === "block")) {
            e.preventDefault();
            window.confirmDeleteTx();
            return;
        }

        const deleteFlatModal = document.getElementById("delete-confirm-modal");
        if (deleteFlatModal && (deleteFlatModal.style.display === "flex" || deleteFlatModal.style.display === "block")) {
            e.preventDefault();
            window.confirmDeleteFlat();
            return;
        }

        const quickPayModal = document.getElementById("quick-pay-confirm-modal");
        if (quickPayModal && (quickPayModal.style.display === "flex" || quickPayModal.style.display === "block")) {
            e.preventDefault();
            window.confirmQuickPay();
            return;
        }
    } else if (e.key === "Escape") {
        const resetPassModal = document.getElementById("reset-pass-confirm-modal");
        if (resetPassModal && resetPassModal.style.display === "flex") {
            resetPassModal.style.display = "none";
        }
        const deleteDocModal = document.getElementById("delete-doc-confirm-modal");
        if (deleteDocModal && deleteDocModal.style.display === "flex") {
            deleteDocModal.style.display = "none";
        }
        const deleteTxModal = document.getElementById("delete-tx-confirm-modal");
        if (deleteTxModal && deleteTxModal.style.display === "flex") {
            deleteTxModal.style.display = "none";
        }
        const deleteFlatModal = document.getElementById("delete-confirm-modal");
        if (deleteFlatModal && deleteFlatModal.style.display === "flex") {
            deleteFlatModal.style.display = "none";
        }
        const quickPayModal = document.getElementById("quick-pay-confirm-modal");
        if (quickPayModal && quickPayModal.style.display === "flex") {
            quickPayModal.style.display = "none";
        }
    }
});

