// ================================================================
// iOS Style Sidebar Drawer Controls (High Performance GPU Accelerated)
// ================================================================
window.openIosSideDrawer = function(e) {
    if (e) {
        if (typeof e.stopPropagation === 'function') e.stopPropagation();
        if (typeof e.preventDefault === 'function') e.preventDefault();
    }
    
    const drawer = document.getElementById("ios-side-drawer");
    if (!drawer) return;
    
    try {
        const curB = state.currentBuilding || (typeof getCurrentBuilding === 'function' ? getCurrentBuilding() : null);
        const bNameEl = document.getElementById("ios-drawer-building-name");
        const roleEl = document.getElementById("ios-drawer-user-role");
        const isEn = (state && state.currentLang === 'en');
        
        if (bNameEl && curB) {
            bNameEl.textContent = curB.name || curB.address || (isEn ? "Condominium" : "Társasház");
        }
        if (roleEl) {
            const isAdmin = state && state.currentUser && state.currentUser.role && state.currentUser.role.toLowerCase() === 'admin';
            roleEl.textContent = isAdmin 
                ? (isEn ? "Common Representative" : "Közös Képviselő")
                : (state && state.currentUser?.flatNum ? `${state.currentUser.flatNum}. lakás` : (isEn ? "Resident" : "Lakó"));
        }

        const finLabelEl = document.getElementById("ios-drawer-menu-finance-label");
        const finIconEl = document.getElementById("ios-drawer-menu-finance-icon");
        const finLinkEl = document.getElementById("ios-drawer-menu-finance");
        if (finLabelEl && finIconEl && finLinkEl) {
            const isAdmin = state && state.currentUser && state.currentUser.role && state.currentUser.role.toLowerCase() === 'admin';
            if (isAdmin) {
                finLabelEl.textContent = isEn ? "Flats Data" : "Lakások adatai";
                finIconEl.style.background = "#4F46E5";
                finIconEl.innerHTML = '<i data-lucide="home" style="width:18px;height:18px;"></i>';
                finLinkEl.setAttribute("onclick", "window.handleMenuOption('flats_data', event)");
            } else {
                finLabelEl.textContent = isEn ? "Building Financial Situation" : "A ház pénzügyi helyzete";
                finIconEl.style.background = "#10B981";
                finIconEl.innerHTML = '<i data-lucide="line-chart" style="width:18px;height:18px;"></i>';
                finLinkEl.setAttribute("onclick", "window.handleMenuOption('finance', event)");
            }
            if (window.lucide) lucide.createIcons();
        }
    } catch (err) {}
    
    drawer.style.display = "flex";
    void drawer.offsetWidth;
    drawer.classList.add("active");
};

window.closeIosSideDrawer = function() {
    const drawer = document.getElementById("ios-side-drawer");
    if (!drawer) return;
    drawer.classList.remove("active");
    setTimeout(() => {
        if (!drawer.classList.contains("active")) {
            drawer.style.display = "none";
        }
    }, 220);
};

window.toggleMenuDropdown = function(e) { window.openIosSideDrawer(e); };
window.toggleMenuDropdownDocs = function(e) { window.openIosSideDrawer(e); };
window.toggleMenuDropdownProfile = function(e) { window.openIosSideDrawer(e); };
window.toggleMenuDropdownFinance = function(e) { window.openIosSideDrawer(e); };
window.toggleMenuDropdownLoans = function(e) { window.openIosSideDrawer(e); };
window.toggleMenuDropdownFlatsData = function(e) { window.openIosSideDrawer(e); };

window.handleMenuOption = function(option, e) {
    if (e) e.preventDefault();
    
    // Close iOS Side Drawer
    window.closeIosSideDrawer();
    
    // Close all menu dropdowns
    const dropdownIds = ["menu-dropdown-content", "menu-dropdown-content-docs", "menu-dropdown-content-profile", "menu-dropdown-content-finance", "menu-dropdown-content-loans", "menu-dropdown-content-flats-data"];
    dropdownIds.forEach(id => {
        const d = document.getElementById(id);
        if (d) d.style.display = "none";
    });
    
    // Close all fullscreen overlays/modals
    window.closeProfileModal();
    window.closeFinancialSituationModal();
    window.closeFlatsDataModal();
    window.closeDocumentsModal();
    window.closeLoansModal();
    
    if (option === 'main') {
        window.goToMainMenu();
    } else if (option === 'docs') {
        window.goToMainMenu();
        window.openDocumentsModal();
    } else if (option === 'loans') {
        window.goToMainMenu();
        window.openLoansModal();
    } else if (option === 'profile') {
        window.goToMainMenu();
        window.openProfileModal();
    } else if (option === 'flats_data') {
        window.goToMainMenu();
        window.openFlatsDataModal();
    } else if (option === 'finance') {
        window.goToMainMenu();
        const isAdmin = state && state.currentUser && state.currentUser.role && state.currentUser.role.toLowerCase() === 'admin';
        if (isAdmin) {
            window.openFlatsDataModal();
        } else {
            window.openFinancialSituationModal();
        }
    } else if (option === 'logout') {
        window.goToMainMenu();
        if (typeof window.performLogout === 'function') {
            window.performLogout();
        } else {
            state.currentUser = null;
            saveStateToLocalStorage();
            updateAppView();
        }
    }
};

window.updateProfileButtonVisibility = function() {
    const btn = document.getElementById("header-profile-btn");
    const modalBtn = document.getElementById("profile-header-switch-btn");
    
    if (!state.currentUser) {
        if (btn) btn.style.display = "none";
        if (modalBtn) modalBtn.style.display = "none";
        return;
    }
    
    const userEmail = (state.currentUser.email || "").toLowerCase().trim();
    if (!userEmail) {
        if (btn) btn.style.display = "none";
        if (modalBtn) modalBtn.style.display = "none";
        return;
    }
    
    const isUserAdminAuthorized = (userEmail === 'benedek.baltay@gmail.com' || userEmail === 'benedek.baltay01@gmail.com' || (state.users || []).some(u => u.email && u.email.toLowerCase().trim() === userEmail && u.role && u.role.toLowerCase() === 'admin'));
    const myFlats = typeof window.getResidentFlats === 'function' ? window.getResidentFlats(userEmail) : (typeof getResidentFlats === 'function' ? getResidentFlats(userEmail) : []);
    
    let profileCount = myFlats.length;
    if (isUserAdminAuthorized) {
        profileCount += 1;
    }
    
    const shouldShow = (profileCount > 1);
    if (btn) btn.style.display = shouldShow ? "flex" : "none";
    if (modalBtn) modalBtn.style.display = shouldShow ? "flex" : "none";
};

let _profileViewSelectedKey = null;

function getFlatCalculatedBalances(building, flat) {
    if (!building || !flat) return { kk: 0, fa: 0, total: 0 };
    
    if (building.id === state.currentBuildingId && flat.balance !== undefined && flat.renovationBalance !== undefined) {
        const kk = flat.balance || 0;
        const fa = flat.renovationBalance || 0;
        return { kk, fa, total: kk + fa };
    }
    
    const flatNum = flat.flatNum;
    const months = getLedgerMonths(flat.startDate);
    
    // KK & FA Monthly Recurring Debits
    let monthlyDebitsKK = 0;
    let monthlyDebitsFA = 0;
    months.forEach(m => {
        const cancelledKeys = [
            `${m.date}_Közös Költség`,
            `${m.date}_KK`
        ];
        if (!flat.cancelledDebits || !flat.cancelledDebits.some(k => cancelledKeys.includes(k))) {
            let amount = flat.monthlyFee || 0;
            const currentMonthDate = new Date(m.date);
            if (flat.feeChangesKK && flat.feeChangesKK.length > 0) {
                const activeChanges = flat.feeChangesKK.filter(c => new Date(c.date) <= currentMonthDate);
                if (activeChanges.length > 0) {
                    activeChanges.sort((a, b) => new Date(b.date) - new Date(a.date));
                    amount = activeChanges[0].amount;
                }
            }
            monthlyDebitsKK += amount;
        }
        
        const cancelledKeysFA = [
            `${m.date}_Felújítási Alap`,
            `${m.date}_FA`
        ];
        if (!flat.cancelledDebits || !flat.cancelledDebits.some(k => cancelledKeysFA.includes(k))) {
            let amount = flat.renovationFee || 0;
            const currentMonthDate = new Date(m.date);
            if (flat.feeChangesFA && flat.feeChangesFA.length > 0) {
                const activeChanges = flat.feeChangesFA.filter(c => new Date(c.date) <= currentMonthDate);
                if (activeChanges.length > 0) {
                    activeChanges.sort((a, b) => new Date(b.date) - new Date(a.date));
                    amount = activeChanges[0].amount;
                }
            }
            monthlyDebitsFA += amount;
        }
    });
    
    const kkTx = (building.transactions || [])
        .filter(tx => tx.flatNum === flatNum && tx.status === "Verified" && (tx.targetAccount === "Közös Költség" || !tx.targetAccount) && tx.type !== "Correction" && tx.method !== "Egyenleg korrekció" && tx.includeInBalance !== false)
        .reduce((sum, tx) => sum + (tx.type === "Debit" ? -Math.abs(tx.amount) : tx.amount), 0);
        
    const kkDebits = (building.manualDebits || [])
        .filter(d => d.flatNum === flatNum && (d.targetAccount === "Közös Költség" || !d.targetAccount) && d.includeInBalance !== false)
        .reduce((sum, d) => sum + Math.abs(d.amount), 0);
        
    const kk = (flat.initialBalance || 0) + kkTx - kkDebits - monthlyDebitsKK;
    
    const faTx = (building.transactions || [])
        .filter(tx => tx.flatNum === flatNum && tx.status === "Verified" && tx.targetAccount === "Felújítási Alap" && tx.type !== "Correction" && tx.method !== "Egyenleg korrekció" && tx.includeInBalance !== false)
        .reduce((sum, tx) => sum + (tx.type === "Debit" ? -Math.abs(tx.amount) : tx.amount), 0);
        
    const faDebits = (building.manualDebits || [])
        .filter(d => d.flatNum === flatNum && d.targetAccount === "Felújítási Alap" && d.includeInBalance !== false)
        .reduce((sum, d) => sum + Math.abs(d.amount), 0);
        
    const fa = (flat.initialRenovationBalance || 0) + faTx - faDebits - monthlyDebitsFA;
    
    return { kk, fa, total: kk + fa };
}

window.handleProfileViewSelectionChange = function(key) {
    _profileViewSelectedKey = key;
    renderProfileModal();
};

window.activateSelectedProfileSession = function() {
    if (!_profileViewSelectedKey) return;
    
    if (_profileViewSelectedKey === 'admin') {
        window.switchToAdminProfile();
        window.closeProfileModal();
        return;
    }
    
    if (_profileViewSelectedKey.startsWith('flat:')) {
        const parts = _profileViewSelectedKey.split(':');
        const buildingId = parts[1];
        const flatNum = parts[2];
        
        if (buildingId && buildingId !== state.currentBuildingId) {
            window.switchBuilding(buildingId);
        }
        window.switchToResidentProfile(flatNum);
        window.closeProfileModal();
    }
};

window.saveBuildingFacilities = function(buildingId) {
    const b = (state.buildings || []).find(x => x.id === buildingId);
    if (!b) return;
    
    const emailEl = document.getElementById(`b-email-${buildingId}`);
    const phoneEl = document.getElementById(`b-phone-${buildingId}`);
    const taxEl = document.getElementById(`b-tax-${buildingId}`);
    const garageEl = document.getElementById(`b-garage-${buildingId}`);
    const garageCountEl = document.getElementById(`b-garage-count-${buildingId}`);
    const basementEl = document.getElementById(`b-basement-${buildingId}`);
    const basementCountEl = document.getElementById(`b-basement-count-${buildingId}`);
    const parkingEl = document.getElementById(`b-parking-${buildingId}`);
    const parkingCountEl = document.getElementById(`b-parking-count-${buildingId}`);
    
    if (emailEl) b.email = emailEl.value.trim();
    if (phoneEl) b.phone = phoneEl.value.trim();
    if (taxEl) b.taxNumber = taxEl.value.trim();
    if (garageEl) b.hasGarage = (garageEl.value === 'yes');
    if (garageCountEl) b.garageCount = parseInt(garageCountEl.value) || 0;
    if (basementEl) b.hasBasement = (basementEl.value === 'yes');
    if (basementCountEl) b.basementCount = parseInt(basementCountEl.value) || 0;
    if (parkingEl) b.hasParking = (parkingEl.value === 'yes');
    if (parkingCountEl) b.parkingCount = parseInt(parkingCountEl.value) || 0;
    
    saveStateToLocalStorage();
    syncStateToCloud();
    playNotificationSound('success');
    
    const isEn = (state.currentLang === 'en');
    const msg = isEn 
        ? `Building data and facility settings for "${b.name}" saved successfully!` 
        : `"${b.name}" adatai és létesítményei sikeresen elmentve!`;
    showToast(msg, 'check-circle-2', '#10b981');
    renderProfileModal();
};

window.saveResidentContactInfo = function(buildingId, flatNum) {
    const b = (state.buildings || []).find(x => x.id === buildingId);
    if (!b) return;
    const flat = (b.flats || []).find(f => f.flatNum === flatNum);
    if (!flat) return;

    const safeId = flatNum.replace(/\s+/g, '-');
    const phoneEl = document.getElementById(`res-phone-${safeId}`);
    const emergNameEl = document.getElementById(`res-emerg-name-${safeId}`);
    const emergPhoneEl = document.getElementById(`res-emerg-phone-${safeId}`);
    const notesEl = document.getElementById(`res-notes-${safeId}`) || document.getElementById(`res-mail-addr-${safeId}`);

    if (phoneEl) flat.phone = phoneEl.value.trim();
    if (emergNameEl) flat.emergencyContactName = emergNameEl.value.trim();
    if (emergPhoneEl) flat.emergencyContactPhone = emergPhoneEl.value.trim();
    if (notesEl) {
        flat.notes = notesEl.value.trim();
        flat.mailingAddress = notesEl.value.trim();
    }

    saveStateToLocalStorage();
    syncStateToCloud();
    playNotificationSound('success');

    const isEn = (state.currentLang === 'en');
    const msg = isEn 
        ? `Contact details for Flat ${flat.flatNum} saved successfully!` 
        : `A(z) ${flat.flatNum}. lakás kapcsolattartási adatai sikeresen elmentve!`;
    showToast(msg, 'check-circle-2', '#10b981');
    renderProfileModal();
};

window.openProfileModal = function() {
    const modal = document.getElementById("profile-modal");
    if (!modal) return;
    
    if (!_profileViewSelectedKey && state.currentUser) {
        if (state.currentUser.role === 'admin') {
            _profileViewSelectedKey = 'admin';
        } else {
            _profileViewSelectedKey = `flat:${state.currentBuildingId || ''}:${state.currentUser.flatNum || ''}`;
        }
    }
    
    renderProfileModal();
    document.body.style.overflow = "hidden";
    modal.style.display = "flex";
    if (window.lucide) lucide.createIcons();
};

window.closeProfileModal = function() {
    const modal = document.getElementById("profile-modal");
    if (modal) modal.style.display = "none";
    document.body.style.overflow = "";
};

